using System.Text.RegularExpressions;
class IntegrationAudit
{
 internal static void Run(Action<string,Action> test,Action<bool,string> check)
 {
  string root=AppContext.BaseDirectory;
  while(!File.Exists(Path.Combine(root,"TownOfHost.csproj"))){var parent=Directory.GetParent(root);if(parent==null)throw new Exception("source not found");root=parent.FullName;}
  string Read(string path)=>File.ReadAllText(Path.Combine(root,path)).Replace("\r\n","\n");
  string Extract(string source,string marker){int start=source.IndexOf(marker,StringComparison.Ordinal);if(start<0)throw new Exception(marker);int opening=source.IndexOf('{',start),depth=1,end=opening+1;while(depth>0){if(source[end]=='{')depth++;if(source[end]=='}')depth--;end++;}return source[start..end];}
  test("common vote hook only after accepted ordinary vote",()=>{string v=Extract(Read("Modules/MeetingVoteManager.cs"),"public void SetVote(");check(v.IndexOf("vote.DoVote(voteFor, numVotes, intentional: isIntentional);")<v.IndexOf("LessThan.OnAcceptedVote("),"callback placement");check(v.Contains("byte originalVoteFor = voteFor;")&&Regex.Matches(v,"LessThan.OnAcceptedVote").Count==1,"original intent preserved");});
  test("pending shared guards run before and finalize after killer callback",()=>{var c=Read("Roles/Core/CustomRoleManager.cs");check(c.IndexOf("targetRole.OnCheckMurderAsTarget(info)")<c.IndexOf("killer.OnCheckMurderAsKiller(info)"),"target guard order");check(c.IndexOf("killer.OnCheckMurderAsKiller(info)")<c.IndexOf("if (info.KillPower <= info.GuardPower"),"power guard order");check(c.Contains("&& force is false)"),"forced-suicide bypass");});
  test("new count type blocks ordinary population wins until resolved",()=>{var raw=Read("Patches/GameEndPredicate/NormalGameEndPredicate.cs");var live=raw[(raw.IndexOf("}*/")+3)..];check(live.Contains("case CountTypes.LessThan: LessThanAlive++; break;"),"count registration");check(Regex.Matches(live,"DaoshiAlive == 0").Count==Regex.Matches(live,"DaoshiAlive == 0 && LessThanAlive == 0").Count,"all existing faction guards");check(live.Contains("if (LessThan.TryChooseWinner()) return true;"),"new population winner");});
  test("same-frame higher-priority crew task victory is checked",()=>{var text=Read("Patches/GameEndPredicate/NormalGameEndPredicate.cs");check(text.Contains("taskPriority.OptionWin.GetInt() > CustomWinnerHolder.WinPriority")&&text.Contains("CheckGameEndByTask(out var taskReason)"),"existing task evaluator must resolve higher priority");});
  test("solo cleanup and number reset precede endgame network emission",()=>{var text=Read("Patches/CheckGameEndPatch.cs");check(text.IndexOf("LessThan.FinalizeSoloWinner();")<text.IndexOf("StartEndGame(reason);"),"single result finalization");check(text.IndexOf("LessThan.EndRound();")<text.IndexOf("CustomWinnerHolder.WriteTo(winnerWriter);"),"number cleanup before winner sync");check(Regex.Matches(text,"if \\(!lockWinner\\) LessThan.TryChooseWinner\\(\\);").Count==2,"draw/sabotage locks");});
  test("Sheriff and Obolus keep old sequential counters unchanged for new target",()=>{var sheriff=Read("Roles/Crewmate/Sheriff.cs");var obolus=Read("Roles/Neutral/Obolus.cs");check(sheriff.Contains("SetUpKillTargetOption(neutral, 40317 - RoleInfo.ConfigId")&&sheriff.Contains("continue;\n            }\n            SetUpKillTargetOption(neutral, idOffset"),"Sheriff isolated ID");check(obolus.Contains("role == CustomRoles.LessThan ? 40318 : role == CustomRoles.Eliminator ? 993015 : RoleInfo.ConfigId + idOffset")&&obolus.Contains("if (role is not CustomRoles.LessThan and not CustomRoles.Eliminator) idOffset++;"),"Obolus isolated ID");});
  test("Faction and Amanojaku exclude only new solo winner from additional-win settings",()=>{check(Read("Roles/AddOns/Neutral/Faction.cs").Contains("role.IsNeutral() && role != CustomRoles.LessThan"),"Faction legacy sequence");check(Read("Roles/AddOns/Crewmate/Amanojaku.cs").Contains("not CustomWinner.Crewmate and not CustomWinner.LessThan"),"Amanojaku legacy sequence");});
  test("all new role translation keys are unique and bilingual",()=>{var csv=Read("Resources/string.csv");foreach(var key in new[]{"LessThan","LessThanInfo","LessThanInfoLong","LessThanShowNumber","LessThanReroll","LessThanRerollUses","LessThanResetEachMeeting","LessThanRerollOthers","LessThanWinPriority","LessThanCanVent"})check(Regex.Matches(csv,"(?m)^\\\""+key+"\\\",").Count==1,"CSV key "+key);check(csv.Contains("自分より小さいものを貪れ"),"intro");});
  test("localized display names preserve priority and vent option identifiers",()=>{check(TownOfHost.TestOptions.All["SoloWinOption"].DisplayName()=="LessThanWinPriority","priority display translation key");check(TownOfHost.TestOptions.All["CanVent"].DisplayName()=="LessThanCanVent","vent display translation key");});
  test("private number path never uses broadcast role RPC helper",()=>{var text=Read("Roles/Neutral/LessThan.cs");check(!text.Contains("CreateSender(")&&!text.Contains("GetProgressText("),"no public role RPC or log progress leak");check(text.Contains("if (client < 0) return;")&&text.Contains("SendOption.Reliable, client)"),"safe explicit recipient");});
 }
}
